Definition pcore_init_a : pcore := mkPC 1 1048576 0 0 0 8192 0 FL_EAGER.

Lemma hz_sh3_pr : forall m A, rw_cells bsegs m A hz_sh3 -> rw_cells bsegs m (A + 34) [CB 44 (poison_bytes 44 0)].
Proof.
  intros m A SH. unfold hz_sh3, hz_sh in SH.
  apply (rw_cells_nth_chunk m A [_; _; _; _; _; _; _; _; _] _ _) in SH. cbn [cells_size csize Nat.add] in SH.
  replace (A + Z.of_nat 34) with (A + 34) in SH by lia. exact SH.
Qed.

