Definition hz_D1_W (lo spa ff : Z) : list (Z * Z) :=
  [(lo, spa); (ff + 272, ff + 624); (Z.shiftr ff 3 + 2147450880 + 34, Z.shiftr ff 3 + 2147450880 + 78)]%Z.

Section HCW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

Definition hz_D1_post (sp gp tp s11 : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (spa ff fp lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m' (pad7 pad2 j13 j32a j8a j32b j8b : list byte),
    ms' = MS (mkR (Z_to_bv 64 P_HZ_RET_SRO) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (spa + 32)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 (ff + 272)) (Z_to_bv 64 (ff + 64)) a4 a5 a6 a7
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 (ff + 208))
                  (Z_to_bv 64 (ff + 64)) (Z_to_bv 64 (ff + 272)) (Z_to_bv 64 (ff + 352)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_SYNC_READ_OP) fc None m' (seg_rom bsegs)
    /\ munch (hz_D1_W lo spa ff) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m' /\ stk bsegs m' lo spa
    /\ rw_cells bsegs m' (ff + 272) (ParserCoreCells pcore_init_a pad7 pad2)
    /\ rw_cells bsegs m' (ff + 352) (NodeCells (init_header_node (ff + 352)) (zeros 4))
    /\ rw_cells bsegs m' (ff + 384) (LNodeCells (init_lheader_node (ff + 384)))
    /\ rw_cells bsegs m' (ff + 400) [C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz 0); C4 (wz 11); C4 (wz 0)]
    /\ rw_cells bsegs m' (ff + 440) (MBufHdrCells (ff + 448) (ff + 448) (ff + 448) 0 0 0 0)
    /\ rw_cells bsegs m' (ff + 504) [C8 (wz (ff + 440))]
    /\ rw_cells bsegs m' (ff + 512) [C1 (b8 0); C1 (b8 0); C1 (b8 0); CB 13 j13]
    /\ rw_cells bsegs m' (ff + 528) [CB 32 j32a; C8 (wz 0); CB 8 j8a]
    /\ rw_cells bsegs m' (ff + 576) [CB 32 j32b; C8 (wz 0); CB 8 j8b]
    /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) hz_sh3
    /\ as_RFS H ((4, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.

