Tactic Notation "hz_acc" hyp(SH3) hyp(MUb) hyp(WMb) ident(ACCx) "by" tactic3(tac) :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SHx := fresh "SHx" in
    pose proof SH3 as SHx; hunkeep SHx; unfold hz_sh3, hz_sh in SHx;
    tr_keep SHx over MUb WMb by tac;
    lazymatch goal with F3x : ?ff mod 8 = 0, APFx : aapp ?ff 1024 |- _ =>
      pose proof (hz_frame_acc mc ff 272 44 _ ltac:(pose proof (aapp_bounds _ _ APFx ltac:(clear; lia)) as (_ & _ & _ & K & _); clear - K; lia) F3x
                    ltac:(clear; lia) ltac:(clear; reflexivity) ltac:(clear; lia)
                    ltac:(pose proof (aapp_bounds _ _ APFx ltac:(clear; lia)) as (_ & _ & K & _); clear - K; lia)
                    ltac:(replace (Z.shiftr ff 3 + 2147450880 + 272 / 8) with (Z.shiftr ff 3 + 2147450880 + 34) by (clear; reflexivity); exact (hz_sh3_pr _ _ SHx))
                    eq_refl) as ACCx;
      change (8 * 44) with 352 in ACCx; clear SHx
    end end.

(* [comment removed for export] *)
Tactic Notation "hz_memset" hyp(M1) constr(dst) constr(n) hyp(SH3) hyp(MUb) hyp(WMb) hyp(PSV1) hyp(WHb) hyp(MU) hyp(FWIN) hyp(RF) hyp(AC) hyp(SK) hyp(FF) "by" tactic3(tac) :=
  lazymatch goal with STx : stk _ ?mc ?lo ?spa, MIx : mem_inv _ ?mc |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
  lazymatch type of M1 with rw_cells _ _ _ [CB _ ?j] =>
  lazymatch goal with F1x : 6832128 + 36864 <= ?ff, F2x : ?ff + 1024 <= aceil, APFx : aapp ?ff 1024, CEILx : aceil <= ?lo, Hhh : asan_rt_hyps ?Hh |- _ =>
    let ACCx := fresh "ACCx" in let SVx := fresh "SVx" in let RFx := fresh "RFx" in let ACx := fresh "ACx" in let SKx := fresh "SKx" in
    hz_acc SH3 MUb WMb ACCx by tac;
    assert (SVx : shvis mc (ff + 272) (ff + 272 + 352))
      by (eapply shvis_transport_hi; [exact PSV1| exact MUb| exact WMb| clear - F1x; lia| unfold AAPP_HI; clear - F2x; pose proof aceil_facts; lia| exact WHb]);
    destruct (fs_frame_writes _ Hhh _ _ _ _ _ _ _ _ _ RF AC SK FF MU ltac:(assumption) FWIN) as (RFx & ACx & SKx);
    lazymatch goal with |- evt _ _ (MS _ ?F _ ?fc _ _ _) =>
    callZc (asan_memset_specZ (ah_memset Hh Hhh) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F fc mc spa dst 0 n j lo) (clear M1 RFx SKx);
    [ clear; lia | exact M1 | clear; lia | clear - F1x; lia
    | eapply accessible_sub; [exact ACCx| clear; lia| clear; lia| clear; lia]
    | eapply shvis_sub; [exact SVx| clear - F1x; lia| clear; lia| clear; lia| clear; lia| clear - F1x; lia]
    | eapply aapp_in_app_mem; [exact APFx| clear; lia| clear; lia]
    | eapply aconst_ok_aapp; [exact APFx| cbn [fst snd]; clear; lia| cbn [fst snd]; clear; lia]
    | exact STx | exact CEILx | tac | tac | left; clear - F2x CEILx; lia | exact MIx | exact ACx | clear ACCx SVx ACx ] end end end end.

