  (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176) -> aceil <= lo -> lo + AFUZZ_STACK <= bv_unsigned sp -> bv_unsigned sp + 64 <= shi ->
  bv_unsigned sp <= 0x7fffffffffff -> fresh_frame H LF 4 ff fp -> as_RHEAP H s LB m ->
  rw_cells bsegs m (ff + 272) [CB 352 jP] ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) hz_sh2 ->
  stk bsegs m lo spa -> mem_inv bsegs m -> as_RFS H ((4, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi ->
  evt bsegs (hz_D1_post sp gp tp s11 F fc LF spa ff fp lo shi m)
    (MS (mkR (Z_to_bv 64 P_HZ_RET_CLR) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 (ff + 208)) (Z_to_bv 64 (ff + 64)) s7 s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
        F (ret_pc (Z_to_bv 64 P_HZ_RET_CLR)) fc None m (seg_rom bsegs)).
